1	/**
2	 * Credential login, registration and password reset. No third-party provider.
3	 *
4	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
5	 *
6	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
7	 * the frozen contract, so the declared `emit` is not reachable from here.
8	 * Registration still publishes `member.joined` — through
9	 * `OrganizationService.createOrganization`, which owns that membership row.
10	 */
11	import {
12	  hashPassword,
13	  hashToken,
14	  randomToken,
15	  verifyPassword,
16	} from "@/lib/hash";
17	import { consumeRateLimit } from "@/lib/rate-limit";
18	import { slugify } from "@/lib/slug";
19	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
20	import * as sessionRepo from "@/server/repositories/session-repository";
21	import * as userRepo from "@/server/repositories/user-repository";
22	import { toIsoTimestamp } from "@/types/common";
23	import { createOrganization } from "./organization-service";
24	import { renderEmail, sendEmail } from "./email-service";
25	import { createSessionToken } from "./session-service";
26	import type {
27	  LoginInput,
28	  PasswordResetConfirmInput,
29	  PasswordResetRequestInput,
30	  RegisterInput,
31	} from "@/schemas/auth";
32	import type { OrgId, SessionId } from "@/types/common";
33	import type { User } from "@/types/member";
34	import type { Organization } from "@/types/organization";
35	
36	/** Buckets guarding the unauthenticated endpoints. */
37	const LOGIN_BUCKET = "auth:login";
38	const RESET_BUCKET = "auth:password-reset";
39	
40	/**
41	 * Rate limiting before a session exists has no tenant to charge against, so
42	 * every unauthenticated attempt is billed to this sentinel bucket.
43	 */
44	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
45	
46	/**
47	 * How long a password-reset link stays usable. Links are minted per request
48	 * and opened straight from the inbox, so a short fuse costs nothing and keeps
49	 * a leaked mailbox from being useful later.
50	 */
51	const RESET_TTL_MS = 60 * 1000;
52	
53	/**
54	 * Registration creates the user and their first workspace in one step — a
55	 * Taskflow account with no organization cannot do anything, so there is no
56	 * intermediate state where one exists without the other.
57	 */
58	export async function register(
59	  input: RegisterInput,
60	): Promise<{ user: User; org: Organization }> {
61	  const existing = await userRepo.findUserByEmail(input.email);
62	  if (existing) {
63	    throw new Error("An account with that email already exists");
64	  }
65	
66	  const user = await userRepo.insertUser({
67	    email: input.email,
68	    name: input.name,
69	    passwordHash: await hashPassword(input.password),
70	  });
71	
72	  const org = await createOrganization(user.id, {
73	    name: `${input.name}'s workspace`,
74	    slug: slugify(input.name) || "workspace",
75	    plan: "free",
76	  });
77	
78	  const welcome = await renderEmail("welcome", {
79	    orgName: org.name,
80	    recipientName: user.name,
81	  });
82	  await sendEmail({ to: user.email, ...welcome });
83	
84	  return { user, org };
85	}
86	
87	/**
88	 * Credential login. The rate limit is charged before the password is checked,
89	 * so a brute-force run is throttled whether or not it guesses correctly, and
90	 * both failure modes return the same message.
91	 */
92	export async function login(
93	  input: LoginInput,
94	): Promise<{ user: User; token: string }> {
95	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
96	  if (!verdict.allowed) {
97	    throw new Error("Too many sign-in attempts; try again shortly");
98	  }
99	
100	  const user = await userRepo.findUserByEmail(input.email);
101	  if (!user) throw new Error("Those credentials did not match");
102	
103	  const storedHash = await userRepo.findPasswordHash(user.id);
104	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
105	    throw new Error("Those credentials did not match");
106	  }
107	
108	  const { token } = await createSessionToken(user.id);
109	
110	  return { user, token };
111	}
112	
113	export async function logout(sessionId: SessionId): Promise<void> {
114	  await sessionRepo.revokeSession(sessionId);
115	}
116	
117	/**
118	 * Always resolves, whether or not the address is known — telling an anonymous
119	 * caller which emails have accounts is an enumeration oracle. Only the token's
120	 * hash is stored; the raw value exists solely inside the email that carries it.
121	 */
122	export async function requestPasswordReset(
123	  input: PasswordResetRequestInput,
124	): Promise<void> {
125	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
126	  if (!verdict.allowed) return;
127	
128	  const user = await userRepo.findUserByEmail(input.email);
129	  if (!user) return;
130	
131	  const token = randomToken(32);
132	  await resetTokenRepo.issueResetToken(
133	    user.id,
134	    hashToken(token),
135	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
136	  );
137	
138	  const message = await renderEmail("password-reset", {
139	    recipientName: user.name,
140	    token,
141	    expiresInMinutes: RESET_TTL_MS / 60_000,
142	  });
143	
144	  await sendEmail({ to: user.email, ...message });
145	}
146	
147	/**
148	 * Consumes a reset token and rewrites the password hash. The token is marked
149	 * used before the new hash is written, so a replay of the same link cannot
150	 * overwrite a password the user has since changed again.
151	 */
152	export async function confirmPasswordReset(
153	  input: PasswordResetConfirmInput,
154	): Promise<User> {
155	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
156	  if (!verdict.allowed) {
157	    throw new Error("Too many reset attempts; try again shortly");
158	  }
159	
160	  const stored = await resetTokenRepo.findLiveResetToken(
161	    hashToken(input.token),
162	  );
163	  if (!stored) throw new Error("That reset link is no longer valid");
164	
165	  await resetTokenRepo.consumeResetToken(stored.id);
166	  await userRepo.updatePasswordHash(
167	    stored.userId,
168	    await hashPassword(input.password),
169	  );
170	
171	  const user = await userRepo.findUserById(stored.userId);
172	  if (!user) throw new Error("That reset link is no longer valid");
173	
174	  return user;
175	}
