19	export async function findUserByEmail(email: string): Promise<User | null> {
20	  const rows = getDb()
21	    .select()
22	    .from(users)
23	    .where(eq(users.email, email.toLowerCase()))
24	    .all();
25	  const row = rows.at(0);
26	  return row ? toUser(row) : null;
27	}
28	
29	export async function insertUser(input: {
30	  email: string;
31	  name: string;
32	  passwordHash: string;
33	}): Promise<User> {
34	  const stamp = toIsoTimestamp(new Date());
35	  const row = getDb()
36	    .insert(users)
37	    .values({
38	      id: newId(),
39	      email: input.email.toLowerCase(),
40	      name: input.name,
41	      passwordHash: input.passwordHash,
42	      avatarUrl: null,
43	      timezone: "UTC",
44	      emailVerifiedAt: null,
45	      createdAt: stamp,
46	      updatedAt: stamp,
47	    })
48	    .returning()
49	    .get();
50	
51	  return toUser(row);
52	}
53	
54	export async function updateUser(
55	  userId: UserId,
56	  patch: UpdateProfileInput,
57	): Promise<User> {
58	  const row = getDb()
59	    .update(users)
60	    .set({
61	      ...(patch.name === undefined ? {} : { name: patch.name }),
62	      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
63	      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
64	      updatedAt: toIsoTimestamp(new Date()),
65	    })
66	    .where(eq(users.id, userId))
67	    .returning()
68	    .get();
69	
70	  if (!row) throw new Error(`User ${userId} not found`);
71	  return toUser(row);
72	}
73	
74	/**
75	 * The password hash never travels on the `User` domain type — nothing outside
76	 * `AuthService` may see it — so login reads it through this narrow accessor.
77	 *
78	 * Not in the manifest: added because `User` deliberately omits the column and
79	 * credential login has no other way to reach it.
80	 */
81	export async function findPasswordHash(
82	  userId: UserId,
83	): Promise<string | null> {
84	  const row = getDb()
85	    .select({ passwordHash: users.passwordHash })
86	    .from(users)
87	    .where(eq(users.id, userId))
88	    .get();
89	  return row?.passwordHash ?? null;
90	}
91	
92	/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
93	export async function updatePasswordHash(
94	  userId: UserId,
95	  passwordHash: string,
96	): Promise<void> {
97	  getDb()
98	    .update(users)
99	    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
100	    .where(eq(users.id, userId))
101	    .run();
102	}
103	
104	/** Batch fetch used by every list view that decorates rows with their author. */
105	export async function findUsersByIds(
106	  userIds: readonly UserId[],
107	): Promise<readonly User[]> {
108	  if (userIds.length === 0) return [];
109	  const rows = getDb()
110	    .select()
111	    .from(users)
112	    .where(inArray(users.id, [...userIds]))
113	    .all();
114	  return rows.map(toUser);
115	}
